update BOK_VALBAL_TABLE_STATUS_ADD a set a.NET_UNIT_VALUE = #{netUnitValueEdit,jdbcType=DECIMAL}, a.ASSET_VALUE = #{assetValueEdit,jdbcType=DECIMAL}, a.CREATE_USER = #{createUser,jdbcType=VARCHAR}, a.CREATE_DEPT = #{createDept,jdbcType=VARCHAR}, a.CREATE_TIME = #{createTime,jdbcType=TIMESTAMP}, a.UPDATE_USER = #{updateUser,jdbcType=VARCHAR}, a.UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP} where 1=1
and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}
and a.val_Date=to_date(#{valDate,jdbcType=DATE},'yyyy-MM-dd')

mapper.select:
